import { User } from "../../domain/user";
import type { UserRepository } from "../../domain/user-repository";
import { toUserDto } from "../dto/user-dto";
import type { CreateUserInput, UserDto } from "../dto/user-dto";
import { translateDomainErrors } from "../errors";

export class CreateUserUseCase {
  constructor(private readonly users: UserRepository) {}

  execute(input: CreateUserInput): UserDto {
    const user = translateDomainErrors(() =>
      User.create(this.users.nextId(), input.name),
    );
    this.users.save(user);
    return toUserDto(user);
  }
}

